window.STUDENTS = [{"key":"cntt","name":"Nguyễn Minh Khang","major":"Công nghệ thông tin","project":"StudyFlow AI","subtitle":"Intelligent Learning & Research Assistant","tagline":"Từ tài liệu và nghiên cứu đến trợ lý học tập AI","summary":"Nghiên cứu tài liệu, tóm tắt paper, quản lý tiến độ và tự động hóa workflow học thuật.","color":"#635BEE","images":{"sessions":{"03":"assets/students/cntt/s03.webp","04":"assets/students/cntt/s04.webp","11":"assets/students/cntt/s11.webp","07":"assets/students/cntt/s07.webp","05":"assets/students/cntt/s05.webp","10":"assets/students/cntt/s10.webp","08":"assets/students/cntt/s08.webp","09":"assets/students/cntt/s09.webp","02":"assets/students/cntt/s02.webp","01":"assets/students/cntt/s01.webp","06":"assets/students/cntt/s06.webp","12":"assets/students/cntt/s12.webp"},"hero_C":"assets/students/cntt/hero_C.webp","ecosystem":"assets/students/cntt/ecosystem.webp","hero_B":"assets/students/cntt/hero_B.webp","hero_A":"assets/students/cntt/hero_A.webp","profile":"assets/students/cntt/profile.webp","hero_D":"assets/students/cntt/hero_D.webp"},"profileText":{"context":"Nguyễn Minh Khang là sinh viên năm 3 ngành Công nghệ Thông tin. Dự án StudyFlow AI hướng tới một nền tảng giúp sinh viên quản lý tài liệu môn học, nghiên cứu, tạo nội dung học thuật, phân tích tiến độ và tự động hóa công việc học tập bằng AI.","problem":"Sinh viên phải đọc nhiều PDF, bài báo và tài liệu kỹ thuật; mất thời gian tổng hợp, ghi chú, viết báo cáo, chuẩn bị slide và theo dõi tiến độ. Các công cụ AI đang được sử dụng riêng lẻ, thiếu một quy trình chung và cơ chế kiểm chứng kết quả.","goal":"Ứng dụng tư duy IMPACT và CREATE vào chuỗi công việc CNTT: xác định vấn đề → quản lý tri thức → nghiên cứu & nội dung học thuật → phân tích dữ liệu → tự động hóa → website & chatbot → governance → tối ưu."},"sessionsDetail":[{"number":1,"topic":"AI Opportunity Discovery – Mô hình IMPACT","title":"AI Opportunity Map","description":"Khang tạo một bản đồ phân tích 6 bước IMPACT (Identify → Map → Produce → Assess → Connect → Transform) cho bài toán học tập và nghiên cứu. Sản phẩm gồm sơ đồ các khó khăn, quy trình hiện tại, cơ hội ứng dụng AI, chỉ số đánh giá và định hướng triển khai StudyFlow AI.","output":"Bản đồ khó khăn học tập/nghiên cứu, quy trình hiện tại, các use case AI, KPI đề xuất và phạm vi yêu cầu của StudyFlow AI.","link":"Đây là bản xác định vấn đề và yêu cầu cho toàn bộ dự án."},{"number":2,"topic":"AI Workflow Design – Thiết kế theo CREATE","title":"Human–AI Workflow Blueprint","description":"Khang thiết kế quy trình phối hợp giữa người và AI theo 6 thành phần CREATE. Sơ đồ thể hiện việc sinh viên cung cấp tài liệu → AI đọc và tổng hợp → sinh viên xác minh nguồn → AI soạn báo cáo → sinh viên phê duyệt → xuất bản. Xác định rõ quyền quyết định, đầu vào, đầu ra và điểm kiểm soát chất lượng.","output":"Swimlane phối hợp sinh viên–AI, sơ đồ xử lý tài liệu đến báo cáo, điểm xác minh nguồn, kiểm soát chất lượng và bước phê duyệt.","link":"Bản thiết kế dùng để triển khai Automated Workflow ở buổi 8."},{"number":3,"topic":"Prompt Engineering – ChatGPT","title":"StudyFlow Prompt Library","description":"Khang xây dựng thư viện 10–15 prompt có cấu trúc chuẩn cho các tác vụ: giải thích code, đọc paper, tìm ý tưởng nghiên cứu, lập đề cương, viết báo cáo, phân tích dữ liệu, tạo câu hỏi ôn tập và kiểm tra chất lượng đầu ra. Mỗi prompt có mục tiêu, bối cảnh, dữ liệu, định dạng đầu ra và tiêu chí đánh giá.","output":"Thư viện 10–15 prompt cho giải thích code, đọc paper, ý tưởng nghiên cứu, lập đề cương, báo cáo, dữ liệu và ôn tập; mẫu đầu vào–đầu ra có tiêu chí kiểm tra.","link":"Các prompt trở thành thành phần xử lý của chatbot và workflow tự động."},{"number":4,"topic":"AI Knowledge Management – Notion AI & NotebookLM","title":"Personal Research Knowledge Hub","description":"Khang xây dựng kho tri thức từ giáo trình, PDF, bài báo khoa học và tài liệu lập trình. Notion tổ chức môn học, chủ đề, ghi chú và tiến độ; NotebookLM hỗ trợ hỏi đáp, tổng hợp và dẫn lại tài liệu nguồn. Sản phẩm có danh mục tài liệu, glossary, research notes và các bộ câu hỏi ôn tập.","output":"Kho Notion môn học/chủ đề/ghi chú/tiến độ, danh mục PDF–paper, glossary, research notes và NotebookLM hỏi đáp có dẫn nguồn.","link":"Kho kiến thức là nguồn đầu vào có kiểm chứng cho báo cáo, website và chatbot."},{"number":5,"topic":"AI Content Creation – Cấu trúc nội dung học thuật","title":"Academic Content Package","description":"Khang tạo bộ nội dung trình bày nghiên cứu về StudyFlow AI: đề cương nghiên cứu, báo cáo kỹ thuật, bản tóm tắt paper, cấu trúc slide thuyết trình và nội dung giới thiệu sản phẩm. Mỗi loại tài liệu có cấu trúc chuẩn, yêu cầu về minh chứng, trích dẫn và chất lượng.","output":"Bộ đề cương nghiên cứu, báo cáo kỹ thuật, tóm tắt paper, cấu trúc slide và nội dung giới thiệu StudyFlow AI có trích dẫn.","link":"Các nội dung trở thành nguồn tư liệu cho slide, website, portfolio và báo cáo cuối kỳ."},{"number":6,"topic":"AI Branding & Communication – Truyền thông đa phương tiện","title":"AI Multimedia Portfolio Assets","description":"Khang chuyển nội dung buổi 5 thành một bộ sản phẩm truyền thông: slide giới thiệu dự án, poster sản phẩm, infographic kiến trúc, video demo ngắn, audio giới thiệu và hình ảnh mô phỏng giao diện. Đồng thời xây dựng phong cách hình ảnh cá nhân để dùng thống nhất trên website portfolio.","output":"Bộ slide, poster, infographic kiến trúc, video demo ngắn, audio giới thiệu và mockup giao diện theo một phong cách thống nhất.","link":"Tạo các tài sản hình ảnh và nội dung cho hai website ở buổi 9."},{"number":7,"topic":"AI Data Analytics – Phân tích và trực quan hóa","title":"Learning Analytics Dashboard","description":"Khang sử dụng dữ liệu học tập mẫu hoặc dữ liệu được phép sử dụng gồm thời gian học, tiến độ đọc tài liệu, mức độ hoàn thành bài tập và hiệu quả sử dụng AI. Sinh viên làm sạch dữ liệu, phân tích xu hướng và tạo dashboard có KPI, biểu đồ, bộ lọc cùng phần nhận xét AI được kiểm chứng.","output":"Dashboard dữ liệu học tập được phép sử dụng: thời gian học, tiến độ tài liệu, mức hoàn thành bài tập, mức sử dụng AI; KPI, biểu đồ, bộ lọc và insights có đối chiếu.","link":"Dashboard sẽ được tích hợp vào StudyFlow AI và cập nhật qua workflow tự động."},{"number":8,"topic":"AI Workflow Automation – Tích hợp toàn bộ quy trình","title":"StudyFlow Automated Research Workflow","description":"Khang hiện thực hóa workflow của buổi 2 bằng công cụ no-code như n8n. Quy trình nhận tài liệu hoặc dữ liệu mới, gọi AI để trích xuất và tóm tắt, lưu kết quả, cập nhật dữ liệu báo cáo và tạo bản nháp nội dung. Các bước cần quyết định được đưa tới sinh viên phê duyệt trước khi xuất bản.","output":"Workflow n8n/no-code với intake tài liệu, AI trích xuất/tóm tắt, cập nhật báo cáo, bản nháp nội dung, nhánh phê duyệt và log thử nghiệm.","link":"Đây là một trong bốn sản phẩm cuối khóa, đồng thời là hệ thống tự động hóa phía sau StudyFlow AI."},{"number":9,"topic":"AI-Powered Web Development – Website và Vibe Coding","title":"2 Published Websites","description":"Khang sử dụng AI hỗ trợ tạo mã, kiểm tra và xuất bản hai website độc lập: Website 1 – Khang's Portfolio: Giới thiệu bản thân, kỹ năng CNTT, CV, chứng chỉ, hình ảnh, video và các dự án đã thực hiện. Website 2 – StudyFlow AI: Ứng dụng học tập có giao diện quản lý tài liệu, danh sách môn học, tiến độ nghiên cứu, trang dashboard và khu vực chatbot dự kiến tích hợp. Hai website có thể được triển khai lên Vercel hoặc nền tảng tương tự và có URL truy cập được.","output":"Hai website độc lập gồm Portfolio của Khang và StudyFlow AI; màn hình desktop/mobile, danh sách môn học, tài liệu, dashboard và vị trí chatbot; URL demo nếu triển khai.","link":"Website sản phẩm là nền tảng để tích hợp chatbot trong buổi 10."},{"number":10,"topic":"AI Chatbot Development – Trợ lý học tập thông minh","title":"StudyFlow AI Research Chatbot","description":"Khang xây dựng chatbot dựa trên kho tài liệu nghiên cứu đã chuẩn bị. Chatbot có khả năng trả lời câu hỏi chuyên ngành CNTT, giải thích khái niệm, hỗ trợ ôn tập và dẫn nguồn tài liệu. Sinh viên thiết kế giao diện hội thoại, giới hạn phạm vi trả lời, thông báo khi thiếu bằng chứng và tích hợp chatbot vào website StudyFlow AI.","output":"Chatbot dựa trên kho tài liệu nghiên cứu, giao diện hội thoại, câu hỏi CNTT/ôn tập, dẫn nguồn, fallback khi thiếu bằng chứng và bộ tình huống kiểm thử.","link":"Hoàn thiện website sản phẩm có AI chatbot hoạt động."}],"page":"hoc-vien-cntt.html","products":[{"name":"n8n Automated Research Workflow","description":"Tiếp nhận tài liệu mới, trích xuất và tóm tắt qua AI, kiểm tra nguồn, xin duyệt trước khi cập nhật báo cáo hoặc kho học tập.","image":"assets/students/cntt/hero_A.webp"},{"name":"Personal IT Portfolio","description":"Giới thiệu CV, kỹ năng CNTT, dự án, năng lực nghiên cứu và hình minh họa sản phẩm StudyFlow AI.","image":"assets/students/cntt/hero_B.webp"},{"name":"StudyFlow AI Website + Research Chatbot","description":"Nền tảng quản lý tài liệu môn học, tiến độ nghiên cứu, dashboard và hỏi đáp theo nguồn tài liệu có giới hạn phạm vi.","image":"assets/students/cntt/hero_C.webp"},{"name":"AI Governance & Optimization Kit","description":"Bộ checklist dữ liệu, bản quyền, chất lượng nguồn, human approval và bản đồ cải tiến AI. Nội dung mở rộng kế thừa từ case 12 buổi ban đầu.","image":"assets/students/cntt/hero_D.webp"}]},{"key":"dulich","name":"Phạm Thảo Vy","major":"Du lịch & Lữ hành","project":"MekongVista AI","subtitle":"Cần Thơ Weekend Discovery","tagline":"Thiết kế hành trình du lịch với AI hỗ trợ","summary":"Nghiên cứu điểm đến, lịch trình 2N1Đ, chăm sóc yêu cầu khách và kiểm chứng thông tin.","color":"#0d9b9e","images":{"sessions":{"03":"assets/students/dulich/s03.webp","11":"assets/students/dulich/s11.webp","08":"assets/students/dulich/s08.webp","02":"assets/students/dulich/s02.webp","12":"assets/students/dulich/s12.webp","06":"assets/students/dulich/s06.webp","01":"assets/students/dulich/s01.webp","09":"assets/students/dulich/s09.webp","04":"assets/students/dulich/s04.webp","07":"assets/students/dulich/s07.webp","10":"assets/students/dulich/s10.webp","05":"assets/students/dulich/s05.webp"},"hero_B":"assets/students/dulich/hero_B.webp","hero_A":"assets/students/dulich/hero_A.webp","hero_D":"assets/students/dulich/hero_D.webp","profile":"assets/students/dulich/profile.webp","ecosystem":"assets/students/dulich/ecosystem.webp","hero_C":"assets/students/dulich/hero_C.webp"},"profileText":{"context":"Phạm Thảo Vy xây dựng MekongVista AI cho hành trình Cần Thơ 2 ngày 1 đêm giả định, kết hợp nghiên cứu điểm đến, thiết kế lịch trình và trải nghiệm du khách.","problem":"Khách tìm thông tin từ nhiều nguồn, khó kết nối điểm tham quan–di chuyển–lưu trú, dễ gặp thông tin giá/giờ lỗi thời. Sinh viên cần biết cách thiết kế trải nghiệm, tư vấn rõ ràng, kiểm tra tính khả thi và tổ chức vận hành có giám sát.","goal":"Giữ nguyên tư duy IMPACT và CREATE; áp dụng theo hành trình du lịch: Destination Research → Tour Design → Guest Communication → Data Analytics → Workflow Automation → Tour Website + Chatbot → Governance → Optimization."},"sessionsDetail":[{"number":1,"topic":"AI Opportunity Discovery – IMPACT","title":"MekongVista AI Opportunity Map","description":"Vy phân tích hành trình khách trẻ tìm tour cuối tuần: thông tin phân tán, khó so sánh lịch trình/chi phí, lo ngại thời tiết – thay đổi giờ hoạt động và phản hồi chậm. Vận dụng 6 bước IMPACT (Identify → Map → Produce → Assess → Connect → Transform) để xác định cơ hội AI ở nghiên cứu điểm đến, thiết kế lịch trình, tư vấn và vận hành dịch vụ.","output":"Bản đồ pain points, 2 persona khách giả định, customer journey (khám phá → hỏi thông tin → lên kế hoạch → đăng ký → trải nghiệm → đánh giá), use cases và KPI dự kiến: inquiry response time, qualified inquiries, itinerary completion, satisfaction.","link":"Đặt bài toán, tập yêu cầu và thước đo cho toàn bộ dự án. Không xem KPI mục tiêu là số liệu thực đo."},{"number":2,"topic":"AI Workflow Design – CREATE","title":"Human–AI Travel Service Blueprint","description":"Vy dùng CREATE (Context → Resources → Execution → Architecture → Trust → Excellence) để thiết kế swimlane Khách / Sinh viên điều hành tour / AI. Chuỗi xử lý: yêu cầu chuyến đi → AI đề xuất hành trình & ngân sách → đối chiếu nguồn và điều kiện vận hành → Vy xác nhận lựa chọn → gửi itinerary → cập nhật yêu cầu dịch vụ. Phương án phải có bước duyệt của người, không tự xác nhận đặt chỗ.","output":"Swimlane Human–AI, ma trận trách nhiệm, checkpoint về giờ mở cửa/giá/điều kiện dịch vụ, nhánh approve–revise, template tour brief.","link":"Là kiến trúc cho n8n buổi 8 và cơ chế phê duyệt trong Governance buổi 11."},{"number":3,"topic":"Prompt Engineering – ChatGPT","title":"Tourism Prompt Library","description":"Tạo thư viện prompt cho nghiên cứu điểm đến, phân khúc khách, thiết kế lịch trình 2N1Đ, tính ngân sách ước tính, so sánh lựa chọn lưu trú/vận chuyển, viết mô tả tour, email xác nhận yêu cầu, dịch/biên tập nội dung, phân tích feedback và FAQ. Mỗi prompt chỉ rõ thông tin đầu vào và yêu cầu AI đánh dấu dữ liệu chưa kiểm chứng.","output":"12–15 prompt chia nhóm Destination Research, Itinerary, Customer Service, Content, Analytics, Safety; mỗi prompt có Mục tiêu → Bối cảnh → Dữ liệu → Đầu ra → Tiêu chí.","link":"Tái sử dụng làm template xử lý yêu cầu khách, chatbot, workflow và nội dung website."},{"number":4,"topic":"AI Knowledge Management – Notion AI & NotebookLM","title":"Destination & Service Knowledge Hub","description":"Vy tổ chức kho tri thức du lịch: bài giới thiệu điểm đến, lịch trình nháp, checklist dịch vụ, FAQ, quy định điểm tham quan, tài liệu chính sách hủy/đổi từ nhà cung cấp và tài liệu an toàn. Notion AI quản lý Tour Bible, Source Registry, Supplier Tracker và lịch công việc; NotebookLM đọc nguồn được cung cấp, tóm tắt và hỏi đáp có dẫn nguồn.","output":"Notion workspace + NotebookLM demo, phân biệt nguồn xác thực / nguồn chờ kiểm tra / giả định; bảng thông tin có ngày cập nhật và người chịu trách nhiệm.","link":"Làm nguồn cho itinerary, thông tin khách, landing page và chatbot; mọi thông tin giờ/giá/tình trạng còn cần xác nhận trước khi sử dụng thực tế."},{"number":5,"topic":"AI Content Creation – Travel Planning & Report","title":"Travel Planning & Content Package","description":"Vy tạo bộ tài liệu cho chương trình Cần Thơ 2N1Đ giả định: Destination Research Brief, Tour Proposal, Day-by-Day Itinerary, Guest Information Sheet và Slide Pitch Outline. Lịch trình có khung thời gian ước tính, hoạt động dự kiến, lựa chọn thay thế khi thời tiết xấu, chi phí dự toán theo nhóm và mục kiểm chứng thông tin.","output":"04 bản chính: Destination Research Report, Tour Proposal & Budget, 2D1N Itinerary, Pitch Deck Outline; kèm FAQ và phương án dự phòng.","link":"Cấp nội dung cho brochure, microsite, chatbot, workflow và portfolio. Đây là mẫu thực hành, chưa phải tour bán thật."},{"number":6,"topic":"AI Branding & Communication – Tourism Multimedia","title":"MekongVista Travel Creative Kit","description":"Vy triển khai bộ nhận diện và truyền thông hành trình trải nghiệm: hero banner, travel poster, 4 social carousel, video short storyboard về hành trình, audio travel guide/podcast, infographic hành trình và slide thuyết trình. Ảnh AI cần gắn nhãn minh họa; không giả là ảnh thực tế từ điểm đến hoặc cơ sở lưu trú.","output":"Travel poster, 4 social cards, 1 storyboard video ngắn, 1 audio guide demo, 1 itinerary infographic, 1 slide pitch deck và brand style mini-guide.","link":"Sử dụng cho website tour, portfolio và nội dung marketing sau khi rà soát nguồn, bản quyền và tính xác thực."},{"number":7,"topic":"AI Data Analytics – Travel Operations","title":"Travel Inquiry & Experience Dashboard","description":"Từ dữ liệu mô phỏng theo kênh và giai đoạn, Vy phân tích số yêu cầu tư vấn, thời gian phản hồi, hành trình được gửi, yêu cầu đủ điều kiện, tỷ lệ chuyển từ inquiry sang booking request, số lần chỉnh sửa lịch trình và điểm hài lòng giả định. AI hỗ trợ nhận xét nhưng nhận xét phải khớp dữ liệu.","output":"Dashboard có KPI cards, inquiry funnel, source channel comparison, weekly trend, tour interest mix, feedback themes và AI insights; ghi rõ “Sample Data”.","link":"Là đầu ra đo lường của workflow và cơ sở đánh giá cải tiến ở buổi 12."},{"number":8,"topic":"AI Workflow Automation – Tourism Operations","title":"MekongVista Automated Tour Inquiry Workflow","description":"Vy cấu hình n8n: Website Inquiry / Google Forms → Google Sheets → AI Extract Requirements → Itinerary Draft + Estimated Budget → Source & Safety Check → Gmail Human Approval → nhánh Approve/Revise → Send Draft Itinerary → Update CRM Sheet & Dashboard. Không tự thực hiện thanh toán, đặt phòng, xuất vé hoặc cam kết còn chỗ.","output":"File n8n JSON demo, bản đồ node, log 2 tình huống Approve/Revise, email itinerary mẫu, Google Sheets CRM và KPI cập nhật.","link":"Sản phẩm cuối kỳ 1; kết nối website, knowledge hub, chatbot và analytics."},{"number":9,"topic":"AI-Powered Web Development – Vibe Coding","title":"02 Websites: Tourism Portfolio & Tour Microsite","description":"Vy tạo (1) Personal Tourism Portfolio giới thiệu CV, kỹ năng Destination Research, Tour Design, Customer Experience, các case study và sản phẩm đa phương tiện; (2) MekongVista Tour Microsite trình bày điểm đến, lịch trình 2N1Đ tham khảo, gallery ảnh minh họa, FAQ, form gửi yêu cầu tư vấn có consent, điều kiện tham khảo và khung chatbot.","output":"Hai website responsive dạng MVP, menu và CTA rõ, form gửi inquiry thử nghiệm, privacy notice, nội dung chú thích “Demo / Sample Itinerary” và link kiểm thử.","link":"Website tour là đầu vào quy trình và nơi gắn chatbot; portfolio tổng hợp năng lực của Vy."},{"number":10,"topic":"AI Chatbot Development – Travel Concierge","title":"MekongVista AI Travel Concierge Chatbot","description":"Chatbot hỗ trợ hỏi đáp về lịch trình mẫu, đối tượng phù hợp, điểm đến, chuẩn bị hành lý, lưu ý thời tiết, chính sách tham khảo, cách gửi yêu cầu tư vấn. Trả lời dựa trên Tour Bible/FAQ đã được duyệt; nếu giá, lịch, thời tiết hoặc dịch vụ chưa kiểm chứng, chatbot phải nói rõ và chuyển câu hỏi cho người phụ trách.","output":"Chat UI gắn microsite, FAQ source cards, 10 tình huống kiểm thử, fallback “Need human confirmation”, nút Contact Tour Advisor, lịch sử thử nghiệm.","link":"Sản phẩm cuối kỳ 3 cùng Tour Microsite; giảm câu trả lời không có nguồn và không tự tạo booking thực."}],"page":"hoc-vien-dulich.html","products":[{"name":"n8n Tour Inquiry Workflow","description":"Xử lý yêu cầu tham khảo tour, AI gợi ý lịch trình và ngân sách, con người xác minh giá, giờ hoạt động và an toàn.","image":"assets/students/dulich/hero_A.webp"},{"name":"Personal Tourism Portfolio","description":"CV, kỹ năng nghiên cứu điểm đến, xây dựng hành trình, chăm sóc khách và case study Cần Thơ.","image":"assets/students/dulich/hero_B.webp"},{"name":"MekongVista Microsite + AI Travel Concierge","description":"Trang tour mẫu 2N1Đ, gallery, FAQ, inquiry form và chatbot trả lời theo Tour Knowledge; không xác nhận booking.","image":"assets/students/dulich/hero_C.webp"},{"name":"Tourism Governance & Performance Kit","description":"Kiểm soát guest consent, độ tin cậy tour facts, supplier checks và chỉ số Sample Data. Nội dung mở rộng từ case cũ.","image":"assets/students/dulich/hero_D.webp"}]},{"key":"marketing","name":"Trần Ngọc Mai","major":"Marketing","project":"GreenNest AI","subtitle":"Refill & Reuse Campaign","tagline":"Từ ý tưởng truyền thông đến hệ sinh thái chiến dịch","summary":"Nghiên cứu thị trường, sáng tạo nội dung, phân tích chiến dịch và quy trình duyệt.","color":"#19a979","images":{"sessions":{"12":"assets/students/marketing/s12.webp","07":"assets/students/marketing/s07.webp","01":"assets/students/marketing/s01.webp","02":"assets/students/marketing/s02.webp","11":"assets/students/marketing/s11.webp","10":"assets/students/marketing/s10.webp","08":"assets/students/marketing/s08.webp","06":"assets/students/marketing/s06.webp","03":"assets/students/marketing/s03.webp","05":"assets/students/marketing/s05.webp","09":"assets/students/marketing/s09.webp","04":"assets/students/marketing/s04.webp"},"hero_A":"assets/students/marketing/hero_A.webp","hero_B":"assets/students/marketing/hero_B.webp","ecosystem":"assets/students/marketing/ecosystem.webp","hero_C":"assets/students/marketing/hero_C.webp","hero_D":"assets/students/marketing/hero_D.webp","profile":"assets/students/marketing/profile.webp"},"profileText":{"context":"Mai là sinh viên Marketing năm 3, xây dựng case study cho GreenNest – nhãn hàng bình nước tái sử dụng hoàn toàn giả định. Chiến dịch “Refill & Reuse” hướng đến sinh viên đại học 18–24 tuổi, khuyến khích thói quen mang bình nước và tham gia thử thách truyền thông. Mọi dữ liệu khách hàng, doanh số và KPI bên dưới là dữ liệu mô phỏng để thực hành.","problem":"Nghiên cứu thị trường, lập brief, tạo nhiều định dạng nội dung, duyệt brand claim, quản lý lịch đăng, đo hiệu quả và xây dựng portfolio đang tách rời. Mai muốn liên kết thành một workflow Marketing có AI hỗ trợ nhưng con người duyệt các quyết định quan trọng.","goal":"Áp dụng đúng tư duy IMPACT/CREATE của khóa học vào công việc Marketing: nghiên cứu → chiến lược → nội dung → dữ liệu → tự động hóa → website + chatbot → governance → tối ưu."},"sessionsDetail":[{"number":1,"topic":"AI Opportunity Discovery – IMPACT","title":"GreenNest AI Opportunity Map","description":"Mai khảo sát vấn đề của chiến dịch “Refill & Reuse” cho bình nước tái sử dụng GreenNest (thương hiệu giả định): người trẻ khó nhớ mang bình, nội dung truyền thông phân tán, đội marketing mất thời gian nghiên cứu và theo dõi. Áp dụng IMPACT: Identify nhu cầu, Map hành trình khách hàng, Produce cơ hội AI, Assess chỉ số, Connect công cụ, Transform thành kế hoạch chiến dịch.","output":"Bản đồ pain points, chân dung khách hàng 18–24 tuổi giả định, customer journey, danh sách use case AI và KPI dự kiến (reach, engagement, CTR, leads, conversion).","link":"Định hướng toàn bộ kế hoạch nội dung, dữ liệu, website và workflow; KPI ở đây là mục tiêu, không phải kết quả đã đạt."},{"number":2,"topic":"AI Workflow Design – CREATE","title":"Human–AI Campaign Workflow Blueprint","description":"Thiết kế quy trình theo CREATE (Context, Resources, Execution, Architecture, Trust, Excellence) với hai vai trò Human và AI: Mai nhập brief → AI đề xuất insight và content → Mai kiểm tra bằng chứng/brand guideline → AI tạo phiên bản bài đăng → Mai duyệt → lên lịch → theo dõi kết quả. Phân biệt các điểm AI được hỗ trợ và quyết định do người chịu trách nhiệm.","output":"Sơ đồ swimlane Human/AI, RACI đơn giản, brand-approval gate, checklist duyệt thông điệp, workflow đầu vào–đầu ra.","link":"Là blueprint triển khai trong buổi 8 và policy duyệt nội dung trong buổi 11."},{"number":3,"topic":"Prompt Engineering – ChatGPT","title":"GreenNest Marketing Prompt Library","description":"Xây dựng 12–15 prompt cho phân khúc khách hàng, phân tích đối thủ, insight, content pillar, caption, SEO outline, ad copy, email, A/B testing, social listening, tóm tắt báo cáo và phân tích dữ liệu. Prompt quy định mục tiêu, bối cảnh, nguồn dữ liệu, đầu ra, tiêu chí và bước kiểm tra claim.","output":"Thư viện prompt với nhóm Market Research, Brand, Content, Ads, Analytics, Reporting; ví dụ đầu vào brief GreenNest và bản nháp đầu ra.","link":"Dùng lại cho kế hoạch chiến dịch, chatbot nội bộ và các node AI của workflow."},{"number":4,"topic":"AI Knowledge Management – Notion AI & NotebookLM","title":"GreenNest Brand & Market Knowledge Hub","description":"Mai lập kho kiến thức gồm brief thương hiệu giả định, chân dung khách hàng, guideline, tài liệu nghiên cứu thị trường, thông tin đối thủ và tài liệu học marketing. Notion AI quản lý database/đầu việc; NotebookLM tóm tắt và hỏi đáp có dẫn nguồn tài liệu đưa vào. Tách rõ dữ liệu thu thập thực tế và giả định.","output":"Workspace Notion AI với Brand Bible, Competitor Tracker, Research Library, Campaign Calendar; NotebookLM có source panel, Q&A và citation.","link":"Là nguồn được kiểm chứng cho nội dung buổi 5–6 và chatbot buổi 10."},{"number":5,"topic":"AI Content Creation – Chiến lược & cấu trúc nội dung","title":"GreenNest Integrated Content Package","description":"Từ insight và nguồn tri thức, Mai xây dựng Campaign Brief, Market Research Report, IMC/Content Strategy, editorial calendar 4 tuần, cấu trúc pitch deck và outline báo cáo kết quả. Nội dung theo hành trình Awareness → Consideration → Conversion; không tự bịa số liệu nghiên cứu hay claim môi trường.","output":"Bộ 4 tài liệu: market research report, campaign proposal, 4-week content calendar, slide outline; kèm bộ 3 content pillars và CTA.","link":"Làm nguyên liệu sản xuất multimedia, feed vào workflow và trang chiến dịch."},{"number":6,"topic":"AI Branding & Communication – Multimedia","title":"GreenNest Creative Campaign Assets","description":"Mai phát triển concept “Refill & Reuse”, key visual, brand tone, social carousel, poster, landing-page banner, video ngắn 15–30 giây, voiceover/podcast clip và pitch deck. Tất cả tài sản phải tuân thủ bộ nhận diện và quy định bản quyền.","output":"Creative kit gồm poster, 3 social posts, 1 video storyboard/demo, 1 audio, 1 infographic và 1 slide pitch deck.","link":"Các asset đưa vào lịch đăng, microsite và portfolio cá nhân."},{"number":7,"topic":"AI Data Analytics – Marketing Performance","title":"GreenNest Campaign Analytics Dashboard","description":"Mai dùng dữ liệu mô phỏng theo ngày và kênh (organic social, email, landing page): impressions, reach, engagement, CTR, leads và conversion. Làm sạch dữ liệu, tạo KPI cards và biểu đồ funnel/kênh/xu hướng; AI gợi ý insight nhưng sinh viên xác nhận bằng dữ liệu.","output":"Marketing dashboard có KPI, channel comparison, conversion funnel, weekly trend, top creatives và insight cards; ghi rõ SAMPLE DATA.","link":"Dashboard là đầu ra của workflow và nguồn đo hiệu suất để tối ưu buổi 12."},{"number":8,"topic":"AI Workflow Automation – Marketing Operations","title":"GreenNest Automated Campaign Workflow","description":"Mai triển khai n8n workflow: nhập ý tưởng/brief Google Sheets → AI soạn caption & bản nháp → kiểm tra brand guideline/claim → gửi yêu cầu duyệt qua Gmail → nhánh Approve/Reject → ghi content calendar và chuẩn bị bản đăng/chuyển vào hàng chờ → cập nhật Sheets & dashboard. Công bố tự động chỉ khi được cấp quyền và có phê duyệt.","output":"File n8n JSON, test log, 1 lượt demo có nhánh Reject và Approve, lịch nội dung được cập nhật và báo cáo tóm tắt.","link":"Một trong bốn sản phẩm cuối kỳ; kết nối kho tri thức, assets, dashboard và website."},{"number":9,"topic":"AI-Powered Web Development – Vibe Coding","title":"2 Published Websites: Portfolio & Campaign Microsite","description":"Mai dùng AI/Vibe Coding làm hai website: (1) Marketing Portfolio – giới thiệu kỹ năng, case study, CV, visual assets và kết quả demo; (2) GreenNest Campaign Microsite – hero “Refill & Reuse”, lợi ích sản phẩm giả định, câu chuyện thương hiệu, gallery, FAQ, đăng ký nhận thông tin và analytics demo. Kiểm tra responsive, CTA, biểu mẫu và nội dung trước khi publish.","output":"Hai URL demo công khai hoặc trong môi trường thử nghiệm, responsive desktop/mobile, form đăng ký có thông báo đồng ý và trang privacy notice.","link":"Microsite là điểm đến chiến dịch; chatbot tích hợp trong buổi 10. Portfolio tập hợp kết quả 12 buổi."},{"number":10,"topic":"AI Chatbot Development – Campaign Assistant","title":"GreenNest Product & Campaign Chatbot","description":"Mai tạo chatbot hỗ trợ khách truy cập microsite: giải thích sản phẩm/chiến dịch, trả lời FAQ theo Brand Knowledge Hub, gợi ý sử dụng bình nước, hướng dẫn đăng ký, chuyển tiếp câu hỏi ngoài phạm vi. Không bịa khuyến mãi/chứng nhận; nếu chưa có bằng chứng phải nêu rõ.","output":"Chatbot UI trong microsite, knowledge base FAQ, 8–10 test questions, citation/source link nội bộ khi phù hợp, fallback và handoff.","link":"Hoàn thiện website chiến dịch + chatbot như một sản phẩm cuối kỳ."}],"page":"hoc-vien-marketing.html","products":[{"name":"n8n Marketing Campaign Workflow","description":"Nhận campaign brief, AI viết nháp, kiểm tra thông điệp/claim, xin duyệt trước khi cập nhật lịch nội dung.","image":"assets/students/marketing/hero_A.webp"},{"name":"Personal Marketing Portfolio","description":"Hồ sơ kỹ năng, chiến dịch GreenNest, dashboard marketing và bộ nội dung sáng tạo.","image":"assets/students/marketing/hero_B.webp"},{"name":"GreenNest Campaign Microsite + Chatbot","description":"Website Refill & Reuse với giới thiệu chiến dịch, CTA, FAQ, consent và chatbot dựa trên nguồn.","image":"assets/students/marketing/hero_C.webp"},{"name":"AI Marketing Governance & Optimization","description":"Kiểm soát claims, consent, bản quyền, phê duyệt và KPI mẫu. Đây là phần mở rộng tham khảo từ case 12 buổi.","image":"assets/students/marketing/hero_D.webp"}]},{"key":"ngonngu","name":"Nguyễn Minh Thư","major":"Ngôn ngữ học","project":"LinguaScope AI","subtitle":"Linguistic Research & Learning Studio","tagline":"Nghiên cứu ngôn ngữ dựa trên nguồn có kiểm chứng","summary":"Corpus, IPA, cú pháp, học liệu ngôn ngữ, nghiên cứu và kiểm duyệt trích dẫn.","color":"#7c62e8","images":{"sessions":{"07":"assets/students/ngonngu/s07.webp","01":"assets/students/ngonngu/s01.webp","10":"assets/students/ngonngu/s10.webp","09":"assets/students/ngonngu/s09.webp","12":"assets/students/ngonngu/s12.webp","04":"assets/students/ngonngu/s04.webp","02":"assets/students/ngonngu/s02.webp","03":"assets/students/ngonngu/s03.webp","11":"assets/students/ngonngu/s11.webp","06":"assets/students/ngonngu/s06.webp","05":"assets/students/ngonngu/s05.webp","08":"assets/students/ngonngu/s08.webp"},"ecosystem":"assets/students/ngonngu/ecosystem.webp","hero_D":"assets/students/ngonngu/hero_D.webp","hero_A":"assets/students/ngonngu/hero_A.webp","hero_C":"assets/students/ngonngu/hero_C.webp","hero_B":"assets/students/ngonngu/hero_B.webp","profile":"assets/students/ngonngu/profile.webp"},"profileText":{"context":"Minh Thư nghiên cứu cách sử dụng AI để phân tích ngữ liệu tiếng Anh, phát triển học liệu ngôn ngữ và hỗ trợ nghiên cứu học thuật. LinguaScope là dự án đào tạo giả định; corpus, người tham gia, bản ghi âm, hiệu quả và KPI chỉ dùng dữ liệu demo/được phép.","problem":"Ngữ liệu văn bản/âm thanh phân tán; việc phiên âm, gán nhãn, phân tích ngữ pháp/ngữ nghĩa và viết báo cáo tốn thời gian; khó kiểm chứng nguồn và phối hợp phản hồi chuyên môn. AI được dùng để hỗ trợ bản nháp, tổ chức tài liệu và tự động hóa, không thay kết luận của giảng viên/người nghiên cứu.","goal":"Ứng dụng IMPACT & CREATE vào chuyên ngành: Research → Corpus & Annotation → Linguistic Analysis → Learning Assets → Analytics → Automation → Research Portal & Chatbot → Governance → Optimization."},"sessionsDetail":[{"number":1,"topic":"AI Opportunity Discovery – IMPACT","title":"LinguaScope Linguistic AI Opportunity Map","description":"Minh Thư khảo sát pain points của việc phân tích dữ liệu ngôn ngữ: transcript rời rạc, gán nhãn thủ công chậm, khó kiểm tra ví dụ ngữ pháp, khó quản lý nguồn và tạo học liệu nhiều định dạng. Áp dụng IMPACT: Identify → Map → Produce → Assess → Connect → Transform để xác định những tác vụ AI hỗ trợ nghiên cứu/ngôn ngữ học.","output":"Opportunity Map 6 bước; persona người học/nghiên cứu giả định; danh sách ứng dụng AI cho phonetics, grammar, semantics, discourse, corpus và translation; KPI mục tiêu về thời gian, độ đầy đủ trích dẫn, chất lượng gán nhãn.","link":"Nền tảng cho corpus, tài liệu nghiên cứu, chatbot và hệ đo lường; KPI chỉ là mục tiêu."},{"number":2,"topic":"AI Workflow Design – CREATE","title":"Human–AI Linguistic Research Blueprint","description":"Thiết kế swimlane Researcher / AI / Faculty Reviewer theo CREATE: Context → Resources → Execution → Architecture → Trust → Excellence. Quy trình Sample Text/Audio → Consent & Source Check → AI Transcription/Annotation Draft → Linguistic Analysis → Human Validation → Approved Research Notes. Nhánh Revise quay về phần phân tích; tách biệt AI hỗ trợ và kết luận chuyên môn.","output":"Swimlane 3 vai trò, RACI cơ bản, các checkpoint kiểm tra consent, transcription accuracy, dữ liệu ngôn ngữ, nguồn, bias và phiên bản.","link":"Blueprint cho workflow n8n buổi 8 và quy định quản trị buổi 11."},{"number":3,"topic":"Prompt Engineering – Linguistics","title":"LinguaScope Linguistics Prompt Library","description":"Xây thư viện 12–15 prompt dùng cho IPA transcription draft, minimal pairs, morphology, syntax trees, semantic roles, pragmatics, discourse analysis, corpus tagging, parallel-text translation review, lesson design và research summary. Mỗi prompt yêu cầu Goal → Context → Sources → Output → Criteria; phản hồi thiếu nguồn phải nêu giới hạn.","output":"Sáu nhóm prompt: Phonetics, Grammar, Semantics, Discourse, Translation, Research & Teaching; ví dụ đầu vào–đầu ra và checklist kiểm chứng.","link":"Dùng lại trong knowledge hub, nội dung học thuật, chatbot và n8n agent."},{"number":4,"topic":"AI Knowledge Management – Notion AI & NotebookLM","title":"LinguaScope Language & Corpus Knowledge Hub","description":"Tạo Notion workspace gồm Corpus Inventory, Linguistic Concepts, Annotation Guidelines, Source Register, Research Log, Lesson Plan. NotebookLM nhập các PDF/tài liệu được phép sử dụng để tổng hợp tài liệu và trả lời có citation; ghi rõ metadata, nguồn, bản quyền và sự đồng ý cho dữ liệu ghi âm.","output":"Notion databases và bộ taxonomy; NotebookLM Source Panel, Cited Q&A, Research Summary; danh mục nguồn có trạng thái verified/pending.","link":"Nguồn căn cứ cho tài liệu buổi 5, học liệu buổi 6, chatbot buổi 10."},{"number":5,"topic":"AI Content Creation – Research Documentation","title":"LinguaScope Linguistic Research Package","description":"Từ corpus demo và tài liệu trong hub, xây bốn đầu ra: Corpus Study Brief, Linguistic Analysis Report, Translation & Terminology Review, Research Presentation Outline. Thể hiện ví dụ IPA, cấu trúc cú pháp, bảng semantic categories, concordance, đối chiếu bản dịch và phương pháp. AI tổng hợp bản nháp; người nghiên cứu xác nhận ví dụ, ngữ cảnh và citation.","output":"4 bản tài liệu có mục tiêu, phương pháp, bảng ví dụ đã kiểm tra, citation placeholder có thật trong nguồn demo và danh sách giới hạn nghiên cứu.","link":"Cung cấp nội dung cho gallery, portal, video học thuật và chatbot."},{"number":6,"topic":"AI Multimedia – Language Education & Communication","title":"LinguaScope Language Learning Multimedia Kit","description":"Sản xuất bộ học liệu cho một chủ đề tiếng Anh học thuật: phonetics pronunciation diagram, IPA infographic, syntax tree explainer, vocabulary/semantics cards, educational slide deck, short video storyboard 30–60 giây, voiceover/TTS demo và subtitle VTT/SRT. Human check âm vị/IPA, trọng âm, ngữ cảnh và quyền sử dụng âm thanh.","output":"1 IPA poster, 1 grammar/semantic infographic, 3 learning cards, 1 pitch/teaching slide outline, 1 video storyboard, 1 audio/subtitle sample.","link":"Assets đưa vào Learning Microsite, portfolio và thư viện tài nguyên."},{"number":7,"topic":"AI Data Analytics – Corpus & Learning Analytics","title":"LinguaScope Corpus & Learning Analytics Dashboard","description":"Phân tích dữ liệu corpus/học tập mô phỏng gồm số câu, tokens, word frequency, POS tags, annotation agreement, review completion, response time và quiz accuracy. Biểu đồ concordance, tag distribution, weekly learning trend và error patterns. Không nhầm KPI mô phỏng với kết quả nghiên cứu đã thực đo.","output":"Dashboard KPI, chart từ dữ liệu mẫu nhất quán, bảng concordance, AI insight cards được kiểm chứng, nhãn Sample Data rõ ràng.","link":"Nguồn phản hồi cho workflow và optimization buổi 12."},{"number":8,"topic":"AI Workflow Automation – Corpus Processing","title":"LinguaScope Automated Corpus & Research Workflow","description":"Xây n8n: Google Form/Drive Submission → File/Consent Check → Extract Text or Transcript Draft → AI POS/Topic Annotation → Source & Quality Check → Gmail Human Approval (Approve/Revise) → Approved Corpus Library → Research Summary → Analytics Dashboard Update. Revise quay lại annotation; không tự công bố transcript hoặc dữ liệu cá nhân.","output":"n8n workflow JSON demo, ảnh sơ đồ, execution log thử hai nhánh Approve/Revise, dataset trước/sau xử lý và bảng QA.","link":"Sản phẩm cuối khóa số 1, nối prompt + source hub + analytics + portal."},{"number":9,"topic":"AI-Powered Web Development – Vibe Coding","title":"Two Websites: Linguistics Portfolio + LinguaScope Research Portal","description":"Dựng (1) Personal Linguistics Portfolio thể hiện CV, research interests, linguistic analysis, teaching assets, translation samples, methodology; (2) LinguaScope Research & Learning Microsite gồm Corpus Explorer, Grammar/Phonetics Demos, Knowledge Library, Research Notes, Quiz Demo, chatbot widget và Privacy/Source Notes. Kiểm tra responsive/accessibility.","output":"2 URL preview/demo, desktop/mobile QA, trang nguồn/bản quyền, file demo public-domain/được phép, consent nếu có form.","link":"Là kênh trưng bày sản phẩm đã được kiểm duyệt; tích hợp chatbot buổi 10."},{"number":10,"topic":"AI Chatbot Development – Source-Grounded Research","title":"LinguaScope AI Linguistics Research Chatbot","description":"Chatbot trên microsite nhận câu hỏi: “What is the difference between phonetics and phonology?”; truy xuất từ Knowledge Hub, đưa câu trả lời ngắn, ví dụ minh họa, Citation Cards theo file/trang, giải thích khác biệt trong ngữ cảnh nghiên cứu. Với câu hỏi thiếu nguồn, hiển thị “Insufficient source – verify with instructor”, không dựng citation hoặc tự chấm điểm phát âm chắc chắn.","output":"Chat UI, knowledge retrieval demo, 8–10 QA test cases, citation panel, fallback, human review queue.","link":"Hoàn thiện sản phẩm cuối khóa số 3: Research Portal + Chatbot."}],"page":"hoc-vien-ngonngu.html","products":[{"name":"n8n Corpus Research Workflow","description":"Nhận dữ liệu văn bản/âm thanh đã được cho phép, AI soạn transcript/annotation, giảng viên kiểm duyệt trước khi đưa vào corpus.","image":"assets/students/ngonngu/hero_A.webp"},{"name":"Personal Linguistics Portfolio","description":"CV, chuyên môn IPA, Syntax, Semantics, nghiên cứu ngôn ngữ, mẫu dịch thuật và tài sản học liệu.","image":"assets/students/ngonngu/hero_B.webp"},{"name":"LinguaScope Portal + Research Chatbot","description":"Corpus Explorer, IPA demo, notes, concept library và chatbot học thuật với nguồn tham khảo demo.","image":"assets/students/ngonngu/hero_C.webp"},{"name":"Linguistic AI Governance & Performance","description":"Consent, quyền corpus, citation QA, dialect fairness và mức độ trưởng thành AI; phần mở rộng từ case 12 buổi.","image":"assets/students/ngonngu/hero_D.webp"}]},{"key":"hospitality","name":"Phạm Bảo Ngọc","major":"Quản lý Nhà hàng – Khách sạn","project":"HorizonStay AI","subtitle":"Boutique Hotel & Dining Experience","tagline":"Nâng cấp trải nghiệm khách và quy trình dịch vụ","summary":"Xử lý yêu cầu khách, quy trình SOP, chatbot lễ tân và phân tích trải nghiệm.","color":"#b89054","images":{"sessions":{"11":"assets/students/hospitality/s11.webp","12":"assets/students/hospitality/s12.webp","09":"assets/students/hospitality/s09.webp","10":"assets/students/hospitality/s10.webp","07":"assets/students/hospitality/s07.webp","05":"assets/students/hospitality/s05.webp","04":"assets/students/hospitality/s04.webp","03":"assets/students/hospitality/s03.webp","02":"assets/students/hospitality/s02.webp","06":"assets/students/hospitality/s06.webp","08":"assets/students/hospitality/s08.webp","01":"assets/students/hospitality/s01.webp"},"hero_D":"assets/students/hospitality/hero_D.webp","hero_C":"assets/students/hospitality/hero_C.webp","hero_A":"assets/students/hospitality/hero_A.webp","ecosystem":"assets/students/hospitality/ecosystem.webp","profile":"assets/students/hospitality/profile.webp","hero_B":"assets/students/hospitality/hero_B.webp"},"profileText":{"context":"Bảo Ngọc xây dựng case study cho một boutique hotel & dining venue hoàn toàn giả định mang tên HorizonStay. Khách gửi yêu cầu thông tin phòng, dùng bữa và dịch vụ; đội lễ tân, nhà hàng và buồng phòng cần phối hợp để phục vụ nhất quán.","problem":"Yêu cầu khách phân tán qua biểu mẫu/email, SOP không tập trung, bàn giao ca thiếu minh bạch, phản hồi chậm. Giá, giờ phục vụ và tình trạng phòng/bàn thay đổi; AI hỗ trợ soạn thảo và phân loại, nhưng con người quyết định thông tin cam kết.","goal":"Áp dụng IMPACT/CREATE: discover guest needs → service blueprint → knowledge → guest communications → analytics → n8n automation → microsite + chatbot → governance → continuous improvement."},"sessionsDetail":[{"number":1,"topic":"AI Opportunity Discovery – IMPACT","title":"HorizonStay AI Hospitality Opportunity Map","description":"Linh khảo sát quy trình tiếp nhận yêu cầu lưu trú và ăn uống tại một boutique hotel kiêm nhà hàng giả định: khách hỏi thông tin nhiều kênh, lịch lễ tân/nhà hàng phân tán, bàn giao ca thiếu nhất quán, phản hồi chậm và thông tin phòng/giá dễ thay đổi. Sử dụng IMPACT (Identify → Map → Produce → Assess → Connect → Transform) để xác định những việc AI được hỗ trợ và các quyết định phải do quản lý xác nhận.","output":"Opportunity Map sáu bước, guest journey, pain-point matrix, 4–6 AI use cases (guest inquiry, service SOP, response drafting, review analytics, workflow), mục tiêu response time và guest satisfaction ghi Sample Data.","link":"Cơ sở cho toàn bộ service blueprint, dữ liệu, chatbot và KPI; không tự nhận đã cải thiện vận hành thực tế."},{"number":2,"topic":"AI Workflow Design – CREATE","title":"Human–AI Hospitality Service Blueprint","description":"Thiết kế swimlane theo CREATE (Context → Resources → Execution → Architecture → Trust → Excellence) với Guest / Front Desk / Restaurant Team / AI / Manager. Luồng: Guest Inquiry → AI Needs Extraction → SOP/Availability Check → Draft Guest Response → Human Review Approve/Revise → Send Draft/Log Request. Nhà hàng xử lý riêng yêu cầu món ăn/dị ứng, bộ phận buồng phòng xác nhận tình trạng vệ sinh; AI không tự hứa giá, phòng trống hoặc bàn trống.","output":"Swimlane, RACI đơn giản, 4 control gates (availability, price, dietary/allergen, privacy), đường Revise quay lại draft, checklist chuyển giao ca.","link":"Blueprint cho n8n buổi 8, quy trình duyệt buổi 11 và kiến thức chatbot."},{"number":3,"topic":"Prompt Engineering – ChatGPT","title":"HorizonStay Hospitality Prompt Library","description":"Thiết kế 12–15 prompt theo cấu trúc Goal → Context → Sources → Output → Criteria: guest persona, inquiry triage, email response, service recovery, dining FAQ, room features, shift handover, SOP summary, feedback sentiment, staff briefing, occupancy explanation và management reporting. Mọi phản hồi cần ghi rõ dữ liệu chưa được xác minh.","output":"Sáu nhóm prompt: Guest Inquiry, Front Desk, Restaurant Service, SOP & Training, Guest Feedback, Operations Analytics; có input/output mẫu và tiêu chí chất lượng.","link":"Tái sử dụng trong knowledge hub, báo cáo, chatbot và AI Agent của n8n."},{"number":4,"topic":"AI Knowledge Management – Notion AI & NotebookLM","title":"HorizonStay Service & SOP Knowledge Hub","description":"Dựng Notion workspace lưu Guest Service SOP, Room & Amenities Guide, Restaurant Menu FAQ, Housekeeping Checklist, Supplier/Staff Contacts (giả định), Complaint Handling và Shift Handover. NotebookLM truy vấn PDF nội quy/SOP, cung cấp bản tóm tắt và Q&A có citation cards; đánh dấu giá, lịch và menu có thể thay đổi.","output":"Notion knowledge base + NotebookLM sources, cited answers, FAQ verified list, document owner, date-of-review và quy trình kiểm tra cập nhật.","link":"Nguồn tham khảo cho tài liệu dịch vụ, chatbot và bước kiểm chứng trong workflow."},{"number":5,"topic":"AI Content Creation – Service Documentation","title":"HorizonStay Guest Service Planning Package","description":"Từ knowledge hub, xây bốn tài liệu: Guest Experience Research Notes, Service Improvement Proposal, Front Desk & Restaurant SOP Mini-Guide, Management Pitch Deck Outline. Có service journey, persona, biểu mẫu check-in request, housekeeping handoff, guest complaint escalation và KPI target minh họa.","output":"Bốn tài liệu có version và nguồn; checklist service recovery, escalation, pricing/availability verification.","link":"Đầu vào cho training assets, chatbot, n8n và hồ sơ portfolio."},{"number":6,"topic":"AI Branding & Communication – Multimedia","title":"HorizonStay Hospitality Experience Content Kit","description":"Tạo key visual boutique hotel/restaurant demo, room & dining brochure, guest welcome card, amenity infographic, digital service menu, bilingual guest FAQ, social post, video storyboard giới thiệu trải nghiệm và orientation slide cho nhân viên. Không mô tả cơ sở vật chất có thật; mọi ảnh và logo là giả định.","output":"Brochure, 3 guest cards, 1 service infographic, 1 FAQ sheet, 1 video storyboard, 1 pitch slide và website hero assets.","link":"Dùng trong microsite, portfolio và knowledge hub; nội dung do con người duyệt trước khi công bố."},{"number":7,"topic":"AI Data Analytics – Hospitality Performance","title":"HorizonStay Guest Experience & Operations Dashboard","description":"Phân tích bộ dữ liệu mô phỏng theo ca/kênh (web inquiry, email, phone notes) về Inquiries, First Response Time, Escalation Rate, Service Requests Resolved, Room Readiness SLA, Restaurant Wait Time, Guest Satisfaction. Hiển thị weekly trends, service-type breakdown, channel comparison và AI Insights cần xác minh.","output":"KPI cards; trend, issue funnel, request categories, service heatmap; dataset/sample assumptions có nhãn Sample Data.","link":"Dashboard nhận log từ n8n và là baseline tối ưu ở buổi 12."},{"number":8,"topic":"AI Workflow Automation – Hospitality Operations","title":"HorizonStay Automated Guest Inquiry Workflow","description":"Triển khai n8n Google Forms / Website Inquiry → Google Sheets CRM → AI Guest Needs Classification → Retrieve Verified SOP/FAQ → Draft Reply & Service Ticket → Safety/Availability/Allergen Check → Gmail Manager Approval → Approve/Revise → Approved Email Draft + Service Task List → Operations Dashboard Update. Revise trở lại bản nháp; không tự xác nhận booking, tính tiền, hoàn tiền hoặc cam kết phòng/bàn.","output":"n8n JSON, screenshot node, test Approve/Revise, sample execution log, CRM/task tracker, dashboard preview.","link":"Sản phẩm cuối khóa số 1; nối tri thức, dịch vụ khách, dashboard và microsite."},{"number":9,"topic":"AI-Powered Web Development – Vibe Coding","title":"Two Websites: Hospitality Portfolio & HorizonStay Microsite","description":"AI/Vibe Coding xây (1) Personal Hospitality Management Portfolio giới thiệu CV, hospitality skills, service process, case study, dashboard; (2) HorizonStay Boutique Hotel & Dining Microsite demo: room gallery, dining story, amenities, FAQs, inquiry form, disclaimer “Sample Property / Availability to Confirm”. Đáp ứng responsive/accessibility/privacy notice.","output":"Hai giao diện desktop/mobile, demo URLs hoặc prototype, feedback form có consent, trạng thái “Request Only”.","link":"Portfolio gom minh chứng 12 buổi; microsite làm giao diện khách và tích hợp chatbot buổi 10."},{"number":10,"topic":"AI Chatbot Development – Guest Concierge","title":"HorizonStay AI Guest & Dining Concierge","description":"Tích hợp chatbot trên microsite, trả lời “Does the hotel offer breakfast?” hoặc “Can I request a quiet room?” dựa trên Room Guide, Dining FAQ, Service SOP; hiển thị citation cards và nguồn review date. Không tự khẳng định giá, phòng trống, giờ hoạt động và chính sách hoàn hủy nếu chưa được xác nhận. Handoff cho lễ tân/nhà hàng khi có yêu cầu đặc biệt, dị ứng hoặc khiếu nại.","output":"Chatbot UI, knowledge source cards, 10 test questions, fallback/human handoff, chính sách không thu thập dữ liệu nhạy cảm không cần thiết.","link":"Sản phẩm cuối khóa số 3 cùng microsite; dữ liệu feedback đưa về phân tích."}],"page":"hoc-vien-hospitality.html","products":[{"name":"n8n Guest Inquiry Workflow","description":"Tập hợp yêu cầu khách, dự thảo phản hồi theo SOP; nhân viên xác minh phòng, giá, dị ứng và duyệt trước khi gửi.","image":"assets/students/hospitality/hero_A.webp"},{"name":"Personal Hospitality Portfolio","description":"CV, kỹ năng lễ tân, F&B, trải nghiệm khách, SOP, báo cáo dịch vụ và case study.","image":"assets/students/hospitality/hero_B.webp"},{"name":"HorizonStay Microsite + AI Concierge","description":"Mô phỏng website khách sạn – nhà hàng với phòng, dining, FAQ, form hỏi thông tin và chatbot hỗ trợ.","image":"assets/students/hospitality/hero_C.webp"},{"name":"Hospitality Governance & Performance","description":"Kiểm soát guest privacy, thông tin phòng, food allergen escalation và chỉ số Sample Data; mở rộng từ case 12 buổi.","image":"assets/students/hospitality/hero_D.webp"}]},{"key":"ai","name":"Lê Minh Anh","major":"Khoa học Dữ liệu & Trí tuệ Nhân tạo","project":"EduPulse AI","subtitle":"Learning Analytics & Research Lab","tagline":"Từ dữ liệu thô đến nghiên cứu có thể kiểm chứng","summary":"Dữ liệu tổng hợp, EDA, mô hình ML cơ sở, báo cáo khoa học và workflow nghiên cứu.","color":"#12a6c4","images":{"sessions":{"04":"assets/students/ai/s04.webp","12":"assets/students/ai/s12.webp","05":"assets/students/ai/s05.webp","08":"assets/students/ai/s08.webp","02":"assets/students/ai/s02.webp","10":"assets/students/ai/s10.webp","11":"assets/students/ai/s11.webp","01":"assets/students/ai/s01.webp","06":"assets/students/ai/s06.webp","07":"assets/students/ai/s07.webp","09":"assets/students/ai/s09.webp","03":"assets/students/ai/s03.webp"},"profile":"assets/students/ai/profile.webp","hero_A":"assets/students/ai/hero_A.webp","ecosystem":"assets/students/ai/ecosystem.webp","hero_B":"assets/students/ai/hero_B.webp","hero_C":"assets/students/ai/hero_C.webp","hero_D":"assets/students/ai/hero_D.webp"},"profileText":{"context":"Minh Anh xây dựng EduPulse AI, một phòng nghiên cứu học tập bằng dữ liệu tổng hợp nhằm khám phá xu hướng học tập, thử nghiệm mô hình ML cơ bản và trình bày kết quả có thể kiểm chứng. Không khai thác dữ liệu cá nhân thật hay dùng AI để xếp loại học viên.","problem":"Dữ liệu CSV phân tán, khó làm sạch, notebook/báo cáo khó tái lập, dashboard cập nhật thủ công; AI có thể hỗ trợ tìm hiểu, code, trực quan hóa và tự động hóa nhưng chuyên viên phải kiểm chứng nguồn, thống kê và đầu ra.","goal":"Vận dụng IMPACT/CREATE vào nghề Data Scientist: đặt câu hỏi → quản trị dữ liệu → xây dựng phân tích & mô hình → trình bày kết quả → tự động hóa → website + chatbot → governance → liên tục tối ưu."},"sessionsDetail":[{"number":1,"topic":"AI Opportunity Discovery – IMPACT","title":"EduPulse AI Opportunity Map","description":"Phân tích khó khăn trong dự án phân tích tiến độ học tập: dữ liệu CSV rời rạc, chất lượng dữ liệu không đồng đều, biểu đồ thủ công, báo cáo khó tái lập. Dùng IMPACT (Identify → Map → Produce → Assess → Connect → Transform) để xác định nhu cầu, quy trình dữ liệu, điểm có thể dùng AI, tiêu chí đánh giá và phương án phát triển MVP.","output":"Bản đồ 6 bước IMPACT; problem statement; danh mục use case EDA, cleaning, reporting, automation; data-flow sơ bộ; KPI dự kiến như thời gian lập báo cáo, tỷ lệ lỗi dữ liệu và mức hoàn thiện báo cáo.","link":"Là khung mục tiêu cho data pipeline, dashboard, website và governance xuyên suốt."},{"number":2,"topic":"AI Workflow Design – CREATE","title":"Human–AI Data Science Workflow Blueprint","description":"Thiết kế quy trình người–AI theo CREATE (Context → Resources → Execution → Architecture → Trust → Excellence): chọn câu hỏi nghiên cứu → kiểm tra quyền sử dụng dữ liệu → AI gợi ý bước tiền xử lý → sinh viên kiểm thử code và thống kê → kiểm tra kết quả/giả định → duyệt báo cáo và dữ liệu công bố. Nhấn mạnh human-in-the-loop và khả năng tái lập.","output":"Sơ đồ swimlane Student / AI / Reviewer; checkpoint schema & data privacy, source verification, code validation, metric review; nhánh Approve/Revise và logging.","link":"Làm bản thiết kế cho n8n buổi 8 và kiểm soát Model/Data Governance buổi 11."},{"number":3,"topic":"Prompt Engineering – ChatGPT","title":"EduPulse Data Science Prompt Library","description":"Tạo thư viện prompt có cấu trúc Goal → Context → Data & Sources → Output → Criteria cho các tác vụ code review Python, SQL query review, EDA planning, missing-value diagnostics, statistical interpretation, experiment design, visualization, model evaluation và executive reporting. AI đề xuất nhưng sinh viên chạy kiểm thử và đối chiếu dữ liệu.","output":"12–15 prompt tái sử dụng thuộc 6 nhóm: Data Cleaning, EDA, Python/SQL, Modeling, Visualization, Research Reporting; 2 prompt mẫu có input/output và checklist kiểm thử.","link":"Được gọi lại trong notebook, AI workflow, chatbot hỏi đáp và tài liệu dự án."},{"number":4,"topic":"AI Knowledge Management – Notion AI & NotebookLM","title":"EduPulse Research & Data Knowledge Hub","description":"Tổ chức kho tri thức khoa học dữ liệu: data dictionary, source registry, experiment notes, methodology, code documentation, model cards và paper review. Notion AI quản lý đầu việc/version; NotebookLM đọc tài liệu phương pháp/PDF và trả lời có trích dẫn nguồn. Tách minh bạch dữ liệu tổng hợp và tài liệu tham khảo.","output":"Notion Research Workspace (Dataset Catalog, Data Dictionary, Experiment Log, Task Board) và NotebookLM với Sources, Cited Q&A, Research Notes, glossary thống kê/ML.","link":"Cấp nguồn cho báo cáo buổi 5, giải thích dashboard, chatbot và audit buổi 11."},{"number":5,"topic":"AI Content Creation – Research & Technical Reporting","title":"EduPulse Research Documentation Package","description":"Biến kết quả phân tích thành bộ tài liệu có cấu trúc học thuật: Research Proposal (Problem, Objectives, Dataset, Methods), EDA Report (Data Quality, Distributions, Insights), Technical Report (Architecture, Pipeline, Validation, Limitations) và Slide Outline (Question, Methods, Results, Limitations, Next Steps). Không khẳng định quan hệ nhân quả chỉ từ tương quan.","output":"Bốn tài liệu draft; bảng mô tả biến; skeleton charts; citation list; note rõ giới hạn dữ liệu mô phỏng và nội dung phải rà soát.","link":"Giải thích sản phẩm trong portfolio, website phân tích và demo capstone."},{"number":6,"topic":"AI Branding & Communication – Data Storytelling","title":"EduPulse Data Science Communication Kit","description":"Thiết kế data-storytelling dễ hiểu từ kết quả EDA, gồm poster khoa học, infographic pipeline, research pitch deck, video storyboard giải thích dữ liệu, audio research summary và banner cho website. AI hỗ trợ phác thảo, con người xác nhận biểu đồ, trục, mẫu số và ngôn ngữ kết luận.","output":"1 research poster, 1 slide deck outline, 1 infographic EDA, 1 data storytelling carousel, 1 storyboard video ngắn, 1 audio script, 1 website hero banner.","link":"Đưa lên dashboard, website sản phẩm và portfolio, có trích dẫn/tuyên bố Sample Data."},{"number":7,"topic":"AI Data Analytics – Exploratory & Predictive Analytics","title":"EduPulse Learning Analytics & Model Dashboard","description":"Dùng bộ dữ liệu học tập tổng hợp để làm EDA, đo missing data, phân tích phân phối, so sánh nhóm và huấn luyện baseline đơn giản dự báo số giờ tự học tuần tiếp theo (regression), tránh tự động quyết định về người học. Tách train/test, kiểm tra leakage và trình bày error metrics, uncertainty/limitations.","output":"Dashboard có Data Quality, Study Hours, Assignment Completion, Cohort Trends, Model MAE/RMSE; bảng so sánh baseline, biểu đồ forecast demo và Data Notes; toàn bộ ghi Sample Data.","link":"Là đầu ra kiểm tra chất lượng và dữ liệu minh chứng cho tự động hóa và tối ưu."},{"number":8,"topic":"AI Workflow Automation – Data & Research Operations","title":"EduPulse Automated Research & Reporting Workflow","description":"Xây MVP trên n8n: Google Drive/Sheets Dataset Intake → Schema Validation → Python/AI Data Quality Notes → EDA Summary Draft → Metric & Source Check → Gmail Human Approval (Approve/Revise) → Report Draft → Dashboard Refresh → Website Draft Update. Nếu không đạt kiểm chứng, nhánh Revise quay về xử lý; không tự công bố chưa duyệt.","output":"Workflow n8n JSON, node map, execution log cho hai nhánh Approve/Revise, bảng dữ liệu đầu vào đã ẩn danh, link dashboard draft và log lỗi.","link":"Sản phẩm cuối khóa số 1; nối knowledge hub, analytics, report và website."},{"number":9,"topic":"AI-Powered Web Development – Vibe Coding","title":"Two Published Websites: Data Science Portfolio & EduPulse Lab","description":"Dùng AI hỗ trợ viết giao diện và kiểm tra để tạo hai website: (1) Personal Data Science Portfolio giới thiệu CV, kỹ năng Python/SQL/ML, dự án và notebooks; (2) EduPulse AI Research Lab gồm Dataset Overview, Interactive Analytics, Model Results, Methodology, Limitations và khu vực chatbot. Giao diện responsive, có nhãn demo.","output":"2 URL demo/preview, desktop/mobile screenshot, source repo hoặc bản mô tả cấu trúc, privacy notice; chart kiểm tra hiển thị và không nhúng dữ liệu cá nhân.","link":"Portfolio giới thiệu minh chứng nghề nghiệp; website sản phẩm nhận cập nhật sau phê duyệt từ workflow."},{"number":10,"topic":"AI Chatbot Development – Research Assistant","title":"EduPulse AI Data & Research Chatbot","description":"Tạo chatbot hỗ trợ hỏi đáp theo dữ liệu mô tả và tài liệu phương pháp đã đưa vào knowledge hub: “What does MAE mean?”, “How was missing data handled?”, “Where does this chart come from?”. Trả lời dựa trên nguồn, đưa citation/source card, không suy diễn kết quả hoặc lộ thông tin người học; chuyển cho tác giả khi chưa đủ nguồn.","output":"Chatbot UI gắn website; RAG/FAQ knowledge base demo; 10 test questions; fallback/handoff; source citations và evaluation checklist cho câu trả lời.","link":"Hoàn thiện website phân tích dữ liệu + chatbot như sản phẩm cuối khóa số 3."}],"page":"hoc-vien-ai.html","products":[{"name":"n8n Automated Research Workflow","description":"Drive CSV Intake → schema check → Python cleaning → AI EDA draft → human metric review → dashboard update.","image":"assets/students/ai/hero_A.webp"},{"name":"Personal Data Science Portfolio","description":"CV, kỹ năng Python/SQL/ML, phân tích dữ liệu, notebooks, biểu đồ và các dự án EduPulse.","image":"assets/students/ai/hero_B.webp"},{"name":"EduPulse Research Lab + AI Chatbot","description":"Website nghiên cứu tổng hợp có EDA/ML baseline, methodology, dashboard và chatbot hỏi đáp trích dẫn nguồn.","image":"assets/students/ai/hero_C.webp"},{"name":"Data & Model Governance Dashboard","description":"Data lineage, bias check, model validation, audit, KPI và 7-level roadmap; phần mở rộng từ case 12 buổi.","image":"assets/students/ai/hero_D.webp"}]},{"key":"dgd","name":"Nguyễn Gia Huy","major":"Thiết kế Đồ họa số (2D)","project":"LUMI Coffee","subtitle":"Visual Identity & Creative AI System","tagline":"Thiết kế nhận diện thương hiệu và workflow sáng tạo có kiểm duyệt","summary":"Thiết kế bộ nhận diện, typography, packaging, creative assets và tự động hóa quy trình thiết kế.","color":"#ea7771","images":{"sessions":{"05":"assets/students/dgd/s05.webp","04":"assets/students/dgd/s04.webp","06":"assets/students/dgd/s06.webp","10":"assets/students/dgd/s10.webp","08":"assets/students/dgd/s08.webp","11":"assets/students/dgd/s11.webp","03":"assets/students/dgd/s03.webp","01":"assets/students/dgd/s01.webp","09":"assets/students/dgd/s09.webp","02":"assets/students/dgd/s02.webp","07":"assets/students/dgd/s07.webp","12":"assets/students/dgd/s12.webp"},"hero_B":"assets/students/dgd/hero_B.webp","hero_A":"assets/students/dgd/hero_A.webp","ecosystem":"assets/students/dgd/ecosystem.webp","profile":"assets/students/dgd/profile.webp","hero_C":"assets/students/dgd/hero_C.webp","hero_D":"assets/students/dgd/hero_D.webp"},"profileText":{"context":"Gia Huy nhận brief xây dựng nhận diện cho LUMI Coffee, một thương hiệu cà phê hoàn toàn giả định. Mục tiêu là thiết kế visual identity system chất lượng, nhiều ứng dụng 2D, có thể trình bày như dự án portfolio thực tế.","problem":"Concept thiếu nhất quán, nguồn tham khảo và giấy phép phân tán; làm poster, menu, bao bì, social thiết kế thủ công lặp lại; feedback/phiên bản khó kiểm soát. AI giúp gợi ý và điều phối nhưng nhà thiết kế quyết định nghệ thuật và chất lượng cuối.","goal":"Áp dụng IMPACT/CREATE vào nghề Graphic Designer: research → art direction → brand system → creative assets → analytics → automation → websites/chatbot → governance → continuous improvement."},"sessionsDetail":[{"number":1,"topic":"AI Opportunity Discovery – IMPACT","title":"LUMI Design Opportunity Map","description":"Gia Huy phân tích bài toán thiết kế bộ nhận diện cho LUMI Coffee (thương hiệu giả định): brief thiếu rõ ràng, moodboard phân tán, khách sửa nhiều vòng, khó giữ đồng nhất màu và typography. Áp dụng IMPACT để Identify vấn đề, Map hành trình thiết kế, Produce cơ hội AI, Assess chất lượng, Connect công cụ và Transform thành kế hoạch xây dựng visual system.","output":"Opportunity Map 6 bước, client persona giả định, design pain points, creative use cases và tiêu chí đánh giá như brand consistency, số vòng sửa, thời gian hoàn thành.","link":"Là creative brief nền tảng cho thiết kế logo, key visual, design workflow và dashboard ở các buổi tiếp theo."},{"number":2,"topic":"AI Workflow Design – CREATE","title":"Human–AI Creative Production Blueprint","description":"Thiết kế Human–AI swimlane theo CREATE: Context (brief & mục tiêu) → Resources (brand references) → Execution (AI concept drafts) → Architecture (asset production flow) → Trust (license, originality, human review) → Excellence (QA và tối ưu). Gia Huy quyết định concept cuối, chỉnh vector, phê duyệt file xuất bản; AI chỉ hỗ trợ.","output":"Swimlane Designer/AI/Reviewer; checkpoint duyệt typography, màu, bản quyền, readability; nhánh Approve/Revise với feedback quay lại draft.","link":"Là bản thiết kế quy trình n8n buổi 8, đồng thời xác định các cổng kiểm soát buổi 11."},{"number":3,"topic":"Prompt Engineering – ChatGPT","title":"LUMI Graphic Design Prompt Library","description":"Gia Huy xây thư viện 12–15 prompt dùng ChatGPT cho phân tích brief, audience insight, moodboard direction, brand naming, color palette reasoning, typography pairing, poster concept, packaging copy, social layouts, design critique và revision notes. Cấu trúc chuẩn: Goal → Context → References → Output → Criteria.","output":"Sáu nhóm prompt: Brief Analysis, Art Direction, Brand Identity, Layout & Type, Design Critique, Production QA; mỗi prompt kèm đầu vào và ví dụ kết quả.","link":"Prompt dùng lại trong Notion/NotebookLM, báo cáo nội dung, quy trình AI Agent và chatbot tư vấn dự án."},{"number":4,"topic":"AI Knowledge Management – Notion AI & NotebookLM","title":"LUMI Brand & Design Knowledge Hub","description":"Tổ chức nguồn tri thức trong Notion AI gồm Client Brief, Brand Bible, Visual References, Asset Inventory, Feedback Tracker và Production Calendar. NotebookLM tổng hợp PDF về thiết kế, guideline, tài liệu nghiên cứu, cho phép hỏi đáp có trích dẫn từ nguồn đã thêm. Tách rõ tài nguyên có license và hình minh họa AI.","output":"Notion workspace với design system & thư viện asset; NotebookLM Sources, Summary, Cited Q&A và Checklist chuyển giao bản thiết kế.","link":"Là một nguồn tham chiếu nhất quán cho tài liệu buổi 5, bộ thiết kế buổi 6 và chatbot buổi 10."},{"number":5,"topic":"AI Content Creation – Design Documentation","title":"LUMI Design Strategy & Content Package","description":"Từ brief và knowledge hub, Gia Huy lập Creative Strategy Document, Brand Concept Proposal, Visual Identity Guidelines và Design Presentation Outline. Bộ tài liệu giải thích định vị, visual tone, palette, grid, typography, ứng dụng logo và nguyên tắc thông điệp, không xem ý tưởng AI là kết quả nghiên cứu đã xác thực.","output":"Bốn file: Creative Brief & Research Notes, Concept Proposal, Brand Guidelines (MVP), Slide Presentation Outline; kèm checklist tính nhất quán thiết kế.","link":"Cung cấp tiêu chuẩn để sản xuất hệ thống assets buổi 6, diễn giải trên website và gửi khách duyệt."},{"number":6,"topic":"AI Branding & Communication – Multimedia","title":"LUMI 2D Brand & Creative Asset Kit","description":"Gia Huy tạo 2–3 concept logo và chọn một phương án để hoàn thiện vector; triển khai key visual, poster A3, 3 social templates, bao bì ly/cốc, menu, infographic, landing banner, short motion storyboard và slide pitch. AI hỗ trợ ý tưởng và hình minh họa; sinh viên tự kiểm tra typography, bố cục, file in ấn và giấy phép.","output":"Logo SVG/PNG, mini brand guideline, 1 poster, 3 social posts, 1 packaging mockup, 1 infographic, 1 motion storyboard, 1 pitch deck.","link":"Asset kit là trung tâm dự án: dùng cho workflow, website thương hiệu, chatbot, portfolio và bài kiểm định chất lượng."},{"number":7,"topic":"AI Data Analytics – Creative Production","title":"LUMI Creative Operations Dashboard","description":"Dùng dữ liệu mô phỏng từ các design tasks để phân tích thời gian từ brief đến approved asset, số vòng revision, on-time delivery, design QA pass rate, asset reuse và AI production cost. AI gợi ý insight nhưng Gia Huy xác nhận dữ liệu nền trước khi quyết định.","output":"Dashboard KPI, production pipeline, weekly trend, revision by asset type, designer review notes; tất cả số liệu đều gắn nhãn Sample Data.","link":"Chỉ số đi vào n8n Workflow (buổi 8) và Performance Optimization (buổi 12)."},{"number":8,"topic":"AI Workflow Automation – Creative Operations","title":"LUMI Automated Design Brief-to-Review Workflow","description":"Triển khai n8n: Google Form/Sheets Brief → AI Brief Parsing → Concept & Copy Draft → Asset Checklist → License/Brand Check → Gmail Human Review → Approve/Revise → Update Asset Tracker → Portfolio/Brand Site Draft Update. Nhánh Revise quay về Concept Draft; không tự xuất bản file chưa duyệt.","output":"Workflow n8n JSON, sơ đồ node, log một lượt Approve và Revise, asset tracker & dashboard được cập nhật, video/demo execution.","link":"Là sản phẩm cuối kỳ số 1 và cầu nối giữa prompt, knowledge hub, creative kit, dashboard và website."},{"number":9,"topic":"AI-Powered Web Development – Vibe Coding","title":"Two Websites: Designer Portfolio + LUMI Brand Showcase","description":"Dùng AI/Vibe Coding xây hai website: (1) Personal Graphic Design Portfolio có bio, skills, selected works, process, CV và case study; (2) LUMI Brand Showcase Microsite trưng bày identity, color & typography system, packaging, gallery, brand story, FAQ và form gửi yêu cầu demo. Kiểm tra responsive, alt text, tốc độ ảnh và tính rõ ràng trước publish.","output":"Hai URL demo/preview, desktop-mobile responsive, gallery asset có chú thích vai trò AI/human, form liên hệ có consent và privacy notice.","link":"Website thương hiệu tích hợp chatbot buổi 10; website cá nhân tập hợp toàn bộ hành trình 12 buổi."},{"number":10,"topic":"AI Chatbot Development – Design Assistant","title":"LUMI Brand Guide & Design FAQ Chatbot","description":"Tạo chatbot trên website LUMI, trả lời câu hỏi về brand palette, font usage, logo safe area, file formats, mẫu ứng dụng và tiến độ request dựa trên Knowledge Hub/Brand Guidelines. Khi thiếu nguồn, chatbot nói chưa đủ thông tin và mời liên hệ Gia Huy; không tự cấp quyền sử dụng thương hiệu hoặc khẳng định logo đã đăng ký bản quyền.","output":"Chatbot UI, FAQ knowledge base, source/citation cards, 10 câu hỏi test, fallback, handoff và hướng dẫn cập nhật tri thức.","link":"Hoàn thiện sản phẩm cuối kỳ số 3: LUMI brand microsite với AI Design Assistant."}],"page":"hoc-vien-dgd.html","products":[{"name":"n8n Automated Creative Workflow","description":"Tiếp nhận brief, tạo concept nháp, kiểm tra bản quyền font/hình, gửi art director duyệt trước khi cập nhật asset library.","image":"assets/students/dgd/hero_A.webp"},{"name":"Personal Graphic Design Portfolio","description":"Portfolio CV, branding, typography, 2D artwork, case study LUMI và quy trình sáng tạo.","image":"assets/students/dgd/hero_B.webp"},{"name":"LUMI Brand Showcase + AI Design Assistant","description":"Microsite nhận diện LUMI với logo, palette, typography, packaging gallery, FAQ và brand chatbot.","image":"assets/students/dgd/hero_C.webp"},{"name":"Creative Governance & Performance Kit","description":"Kiểm soát quyền ảnh/font, tính nhất quán thương hiệu, phiên bản asset, KPI mẫu và 7-level roadmap; phần mở rộng.","image":"assets/students/dgd/hero_D.webp"}]},{"name":"Trần Quốc Bảo","major":"Luật","project":"LexBridge AI","subtitle":"Contract Review & Legal Research Studio","tagline":"Nghiên cứu hợp đồng dịch vụ website mẫu với AI hỗ trợ và giám sát của người hướng dẫn.","summary":"Rà soát hợp đồng, tra cứu nguồn, viết legal memo và tự động hóa quy trình kiểm duyệt có trách nhiệm.","color":"#D19C3C","profileText":{"context":"Trần Quốc Bảo là nam sinh viên năm 3 ngành Luật, thực hành trên bộ hồ sơ hợp đồng dịch vụ thiết kế website hoàn toàn giả định. Người hướng dẫn giữ vai trò kiểm tra nguồn và xác nhận nội dung pháp lý; không sử dụng hồ sơ khách hàng thật.","problem":"Hợp đồng và tài liệu tham khảo phân tán, điều khoản khó đối chiếu, nguồn có thể đã lỗi thời và quá trình rà soát thủ công chậm. AI chỉ hỗ trợ phân tích, phân loại và soạn nháp, không thay thế người có chuyên môn.","goal":"Vận dụng IMPACT và CREATE vào nghiên cứu pháp lý: nhận diện vấn đề → xây kho nguồn → phân tích điều khoản → memo dự thảo → dashboard → tự động hóa có duyệt → microsite và trợ lý hỏi đáp có trích dẫn."},"products":[{"name":"n8n Contract Review Workflow + Supervisor Approval","description":"Tiếp nhận case mẫu, trích xuất hợp đồng PDF, gợi ý phân loại điều khoản, rà nguồn, soạn issue draft; mọi bản ghi nhớ chuyển người hướng dẫn duyệt trước khi đưa vào bộ hồ sơ. Không ký hoặc gửi tư vấn pháp lý tự động.","image":"assets/students/luat/hero_A.webp"},{"name":"Personal Law Student Portfolio","description":"Hồ sơ năng lực nghiên cứu pháp lý, kỹ năng đọc hợp đồng, viết legal memo, dự án, sản phẩm học thuật và minh chứng khả năng sử dụng AI có trách nhiệm.","image":"assets/students/luat/hero_B.webp"},{"name":"LexBridge Case Microsite + Cited AI Assistant","description":"Website demo trình bày case, clause library, nghiên cứu nguồn và chatbot giải thích theo tài liệu được cung cấp; không đủ nguồn thì chuyển người có chuyên môn xác minh.","image":"assets/students/luat/hero_C.webp"},{"name":"Legal AI Governance & Performance Kit","description":"Bộ tiêu chí bảo mật, quyền truy cập, kiểm chứng hiệu lực và nguồn, chống hallucination, human approval, audit log, dashboard hiệu quả và roadmap 7 cấp (nội dung mở rộng).","image":"assets/students/luat/hero_D.webp"}],"key":"luat","images":{"sessions":{"01":"assets/students/luat/s01.webp","02":"assets/students/luat/s02.webp","03":"assets/students/luat/s03.webp","04":"assets/students/luat/s04.webp","05":"assets/students/luat/s05.webp","06":"assets/students/luat/s06.webp","07":"assets/students/luat/s07.webp","08":"assets/students/luat/s08.webp","09":"assets/students/luat/s09.webp","10":"assets/students/luat/s10.webp","11":"assets/students/luat/s11.webp","12":"assets/students/luat/s12.webp"},"profile":"assets/students/luat/profile.webp","ecosystem":"assets/students/luat/ecosystem.webp","hero_A":"assets/students/luat/hero_A.webp","hero_B":"assets/students/luat/hero_B.webp","hero_C":"assets/students/luat/hero_C.webp","hero_D":"assets/students/luat/hero_D.webp"},"page":"hoc-vien-luat.html","sessionsDetail":[{"number":1,"topic":"AI Opportunity Discovery – IMPACT","title":"LexBridge Legal Opportunity Map","description":"Quốc Bảo phân tích khó khăn khi nghiên cứu và rà soát hợp đồng dịch vụ website: tài liệu nằm nhiều nơi, khó theo dõi phiên bản, điều khoản thiếu nhất quán, trích dẫn nguồn dễ sai và mất thời gian tổng hợp. Dùng IMPACT để xác định vấn đề, lập bản đồ quy trình, đề xuất AI, đánh giá rủi ro, kết nối công cụ và thiết kế phương án cải tiến.","output":"Opportunity Map 6 bước, stakeholder map, danh mục pain points, 5 use case AI, KPI mục tiêu về thời gian rà soát, completeness và citation quality.","link":"Là bài toán nền cho Legal Knowledge Hub, workflow kiểm tra hợp đồng, dashboard và website."},{"number":2,"topic":"Human–AI Legal Workflow – CREATE","title":"Human–AI Contract Review Blueprint","description":"Thiết kế CREATE: Context (phạm vi yêu cầu), Resources (hợp đồng và nguồn luật), Execution (AI đọc/đối chiếu), Architecture (luồng xử lý), Trust (bảo mật, nguồn, human review), Excellence (chất lượng bàn giao). Swimlane Client/Student/AI/Supervisor; bước kiểm tra pháp lý và kết luận cuối thuộc người có chuyên môn.","output":"Swimlane Intake → OCR/Extraction → Clause Mapping → Legal Source Check → Issue Draft → Human Approve/Revise → Review Memo; checkpoint bắt buộc và nhánh sửa.","link":"Blueprint cho workflow n8n buổi 8 và chính sách kiểm soát buổi 11."},{"number":3,"topic":"Prompt Engineering – Legal Research","title":"LexBridge Legal Prompt Library","description":"Xây dựng thư viện prompt theo Goal → Context → Sources → Output → Criteria; yêu cầu AI nêu rõ căn cứ, giới hạn thẩm quyền, ngày hiệu lực cần xác minh, vùng không chắc chắn và tránh tạo điều luật giả.","output":"6 nhóm Legal Research, Clause Extraction, Contract Comparison, Issue Spotting, Memo Drafting, Citation Check; 12–15 prompt có input, output và checklist kiểm tra.","link":"Dùng chung cho tri thức, văn bản buổi 5, chatbot và AI Agent."},{"number":4,"topic":"AI Knowledge Management – Notion AI & NotebookLM","title":"LexBridge Legal Knowledge Hub","description":"Tổ chức Notion AI theo hồ sơ, bên liên quan, hợp đồng mẫu, bản sửa, issue tracker; NotebookLM chứa tài liệu được phép sử dụng và bản trích dẫn, Q&A theo nguồn. Phân biệt dữ liệu giả định với nguồn pháp luật chính thống được xác minh.","output":"Notion Case Workspace, Contract Repository, Clause Taxonomy, Version Tracker; NotebookLM source library, cited Q&A, source status và ngày kiểm tra.","link":"Kho tham chiếu cho legal memo, chatbot và source verification."},{"number":5,"topic":"AI Content Creation – Legal Documentation","title":"LexBridge Legal Documentation Package","description":"Tạo bốn tài liệu dựa trên cùng một bộ hồ sơ hợp đồng giả định: Legal Research Note, Contract Review Memo, Clause Comparison Table và Client Briefing Slide Outline. Phân biệt facts, issues, analysis và recommendations pending review.","output":"4 bản thảo có nguồn trích dẫn và thời điểm kiểm tra, red-flag notes, disclaimer về tính chất học tập, phiếu duyệt của giảng viên/người hướng dẫn.","link":"Dùng cho microsite, portfolio, AI Assistant và lịch sử rà soát."},{"number":6,"topic":"AI Multimedia – Legal Communication","title":"LexBridge Legal Explainer & Visual Kit","description":"Chuyển nội dung pháp lý phức tạp thành hình minh họa dễ hiểu: contract lifecycle, obligation matrix, clause risk infographic, client FAQ card, slide deck, short video storyboard và audio legal-literacy guide. Không tự nhận tài liệu là tư vấn pháp lý cá nhân.","output":"1 infographic hợp đồng, 1 risk heatmap, 4 FAQ cards, 1 slide deck, 1 short-video storyboard, 1 audio-script, 1 microsite banner.","link":"Tài sản trực quan dùng cho website, portfolio và trình bày case study."},{"number":7,"topic":"AI Data Analytics – Legal Operations","title":"LexBridge Contract Review Analytics Dashboard","description":"Sử dụng dữ liệu hợp đồng giả định để đo số hồ sơ, loại điều khoản, review turnaround, issue severity, source-verified ratio, human approval rate và AI-assisted drafting time. Không xem các số liệu đó là kết quả pháp lý thực tế.","output":"Dashboard KPI, clause distribution, issue funnel, weekly trend, reviewer workload và AI Insights gắn nhãn Sample Data.","link":"Cập nhật qua n8n và dùng cho Performance Optimization."},{"number":8,"topic":"AI Workflow Automation – Legal Review","title":"LexBridge Automated Contract Review Workflow","description":"Xây workflow n8n: Website Intake/Form → Secure Case Register → PDF/Text Extraction → AI Clause Mapping → Source Check → Risk Flag Draft → Gmail Human Approval → Approve/Revise → Memo Draft → Case Tracker/Dashboard. Nhánh Revise quay về bản nháp; không tự ký, gửi tư vấn hoặc xác nhận hợp đồng.","output":"n8n JSON demo, luồng Approve/Revise, source-check log, version log, email draft chưa gửi, tracker cập nhật.","link":"Sản phẩm cuối khóa 1, kết nối kho tài liệu, bản ghi nhớ và các dashboard."},{"number":9,"topic":"AI-Powered Web Development – Vibe Coding","title":"Two Websites: Legal Portfolio + LexBridge Case Microsite","description":"Tạo hai website responsive: Personal Law Student Portfolio giới thiệu năng lực nghiên cứu và sản phẩm học thuật; LexBridge Case Microsite hiển thị case giả định, contract review stages, clause insights, source bibliography, FAQ và form tiếp nhận bản demo có consent.","output":"2 URL demo/preview, desktop/mobile, section CV/case studies, portal trạng thái Draft/Under Review, policy notice, form có privacy notice.","link":"Sản phẩm cuối khóa 2 và nền tảng cho AI Legal Research Assistant."},{"number":10,"topic":"AI Research Assistant – Cited Q&A","title":"LexBridge AI Legal Research Assistant","description":"Xây chatbot hỗ trợ hỏi đáp trong phạm vi nguồn văn bản đã nạp: giải thích thuật ngữ, tóm tắt điều khoản, chỉ rõ trang/đoạn nguồn và mức độ chắc chắn. Nếu thiếu nguồn hoặc văn bản hiệu lực không rõ, trả lời không đủ căn cứ và yêu cầu người hướng dẫn xác minh.","output":"Demo question “Which clauses need review before signing this sample service agreement?”, answer có citation cards, source preview, human verification gate và fallback.","link":"Sản phẩm cuối khóa 3 (ghép website + chatbot); không được công bố là dịch vụ tư vấn luật."}]},{"name":"Nguyễn Khánh Vy","major":"Tài chính – Kế toán – Ngân hàng","project":"FinBridge AI","subtitle":"Finance, Accounting & Banking Operations Lab","tagline":"Đối chiếu sao kê, phân tích dòng tiền và báo cáo tài chính từ dữ liệu hoàn toàn mô phỏng.","summary":"Chuẩn hóa chứng từ, đối soát giao dịch, lập báo cáo dòng tiền và tự động hóa có người phê duyệt.","color":"#087A60","profileText":{"context":"Nguyễn Khánh Vy là nữ sinh viên năm 3 ngành Tài chính – Kế toán – Ngân hàng, xây dựng mô hình doanh nghiệp dịch vụ giả định FinBridge với sao kê CSV, hóa đơn, dòng tiền và ngân sách mẫu. Không kết nối tài khoản hoặc khách hàng thật.","problem":"Sao kê và hóa đơn nằm ở nhiều tệp, đối chiếu thủ công mất thời gian, dễ thiếu mã tham chiếu, sai phân loại và chậm tổng hợp báo cáo. AI gợi ý ghép giao dịch, tìm ngoại lệ nhưng quyết định vẫn thuộc kế toán và kiểm soát viên.","goal":"Vận dụng IMPACT và CREATE trong Finance Operations: phân tích bài toán → tổ chức SOP và tri thức → tạo bản nháp báo cáo → analytics → workflow đối soát có phê duyệt → portfolio, portal và AI Assistant có trích dẫn."},"products":[{"name":"Automated Reconciliation & Document Review Workflow","description":"n8n nhận sao kê và hóa đơn mẫu, kiểm tra schema, trùng lặp, phân loại giao dịch, gợi ý ghép invoice và chuyển ngoại lệ cho người kiểm tra, chỉ cập nhật bảng dự thảo sau phê duyệt.","image":"assets/students/taichinh/hero_A.webp"},{"name":"Personal Finance & Banking Portfolio","description":"Website CV và học liệu minh chứng kỹ năng Excel, SQL, Power BI, kế toán tài chính, phân tích dòng tiền, báo cáo cùng các case study AI tự động hóa.","image":"assets/students/taichinh/hero_B.webp"},{"name":"FinBridge Operations Portal + AI Finance Assistant","description":"Portal demo cho Transaction Review, Cash Flow, Reconciliation và báo cáo, với chatbot giải thích nghiệp vụ dựa trên SOP mẫu, citation cards và escalation khi thiếu nguồn.","image":"assets/students/taichinh/hero_C.webp"},{"name":"AI Financial Governance & Performance Kit","description":"Kiểm soát dữ liệu, tính toán, phân quyền, phê duyệt, rủi ro, nhật ký kiểm toán cùng KPI giả định và lộ trình trưởng thành AI 7 cấp (nội dung mở rộng).","image":"assets/students/taichinh/hero_D.webp"}],"key":"taichinh","images":{"sessions":{"01":"assets/students/taichinh/s01.webp","02":"assets/students/taichinh/s02.webp","03":"assets/students/taichinh/s03.webp","04":"assets/students/taichinh/s04.webp","05":"assets/students/taichinh/s05.webp","06":"assets/students/taichinh/s06.webp","07":"assets/students/taichinh/s07.webp","08":"assets/students/taichinh/s08.webp","09":"assets/students/taichinh/s09.webp","10":"assets/students/taichinh/s10.webp","11":"assets/students/taichinh/s11.webp","12":"assets/students/taichinh/s12.webp"},"profile":"assets/students/taichinh/profile.webp","ecosystem":"assets/students/taichinh/ecosystem.webp","hero_A":"assets/students/taichinh/hero_A.webp","hero_B":"assets/students/taichinh/hero_B.webp","hero_C":"assets/students/taichinh/hero_C.webp","hero_D":"assets/students/taichinh/hero_D.webp"},"page":"hoc-vien-taichinh.html","sessionsDetail":[{"number":1,"topic":"AI Opportunity Discovery – IMPACT","title":"FinBridge AI Finance Opportunity Map","description":"Khánh Vy phân tích các vấn đề trong quy trình xử lý chứng từ và đối chiếu tài khoản của doanh nghiệp mô phỏng: file sao kê rời rạc, nhập liệu thủ công, chứng từ thiếu trường, khó theo dõi thanh toán và chậm lập báo cáo. Áp dụng IMPACT: Identify → Map → Produce → Assess → Connect → Transform.","output":"Opportunity map với pain points, luồng chứng từ–giao dịch, 4–5 use case AI, các KPI dự kiến như thời gian đối soát, tỷ lệ khớp, tỷ lệ ngoại lệ và thời gian lập báo cáo.","link":"Định hướng toàn bộ dữ liệu đầu vào, quy trình phê duyệt, phân tích và cổng nghiệp vụ."},{"number":2,"topic":"AI Workflow Design – CREATE","title":"Human–AI Finance Operations Blueprint","description":"Theo CREATE (Context → Resources → Execution → Architecture → Trust → Excellence), thiết kế swimlane Kế toán / AI / Quản lý: nhận dữ liệu → phân loại → kiểm tra số dư & mã tham chiếu → gợi ý ghép hóa đơn–giao dịch → rà soát ngoại lệ → người có thẩm quyền Approve/Revise → cập nhật báo cáo dự thảo.","output":"Sơ đồ swimlane, source-of-truth matrix, trách nhiệm phê duyệt, checklist kiểm tra chênh lệch và điểm dừng trước ghi sổ/thanh toán.","link":"Blueprint để triển khai n8n buổi 8 và governance buổi 11."},{"number":3,"topic":"Prompt Engineering – Finance Tasks","title":"FinBridge Finance Prompt Library","description":"Xây dựng thư viện 12–15 prompt cho Document Extraction, Transaction Categorization, Reconciliation Checks, Cash Flow Summary, Variance Analysis, Bank Product Comparison (educational) và Management Reporting. Prompt gồm Goal → Context → Data & Sources → Output → Criteria; không yêu cầu AI khẳng định kết quả chưa kiểm tra.","output":"6 nhóm prompt có brief mẫu, định dạng JSON/bảng và checklist kết quả, kèm cảnh báo dữ liệu giả định.","link":"Dùng cho các bản nháp báo cáo, trợ lý AI và node workflow."},{"number":4,"topic":"Knowledge Management – Notion AI & NotebookLM","title":"FinBridge Accounting & Banking Knowledge Hub","description":"Tổ chức bộ dữ liệu mô phỏng, biểu mẫu hóa đơn, sổ tay tài khoản, quy trình đối soát, glossary ngân hàng, lịch công việc và tài liệu học thuật được phép sử dụng. Notion quản lý Data Dictionary/Controls/Task Tracker; NotebookLM cung cấp tóm tắt và Q&A có nguồn.","output":"Notion workspace (Document Register, Policy Notes, Reconciliation SOP, Task Board) và NotebookLM (source PDFs, source dates, cited Q&A).","link":"Nguồn cho soạn báo cáo, chatbot và bước verification."},{"number":5,"topic":"AI Content Creation – Business Documentation","title":"FinBridge Financial Reporting Package","description":"Từ dữ liệu mẫu, cấu trúc 4 tài liệu gồm Transaction Reconciliation Report, Monthly Cash Flow Summary, Budget vs Actual Review và Management Pitch Deck. Nêu giả định, kỳ báo cáo, công thức tính, ngoại lệ và giới hạn của nguồn.","output":"Bộ 4 preview tài liệu có bảng đối soát, cash-flow chart, variance table và slide executive summary.","link":"Nguồn nội dung cho bảng điều khiển, website và portfolio."},{"number":6,"topic":"AI Communication & Multimedia","title":"FinBridge Financial Communication Kit","description":"Tạo các tài sản trực quan phục vụ giải thích nghiệp vụ: infographic luồng hóa đơn–giao dịch, poster kiểm soát chi phí, slide cash flow, dashboard snapshot, video storyboard 30 giây, audio report summary và website banner. Không sử dụng logo ngân hàng có thật.","output":"1 infographic, 1 poster, 3 slide, 1 video storyboard, 1 audio script và 1 banner demo.","link":"Dùng trong learning portal, báo cáo và portfolio."},{"number":7,"topic":"Finance & Banking Analytics","title":"FinBridge Transaction & Cash Flow Dashboard","description":"Dùng giao dịch tổng hợp giả lập theo ngày và nhóm chi phí, dữ liệu công nợ & hóa đơn, tính Inflow, Outflow, Net Cash Flow, Matched Transactions, Exceptions, Budget Variance. Minh họa trend, waterfall và aging với định nghĩa rõ.","output":"SaaS analytics dashboard trên laptop: KPI cards, cash-flow trend, transaction category, exception funnel và AI Insights (Sample Data).","link":"Báo cáo đầu ra buổi 8 và baseline hiệu quả buổi 12."},{"number":8,"topic":"AI Workflow Automation – n8n","title":"FinBridge Automated Reconciliation Workflow","description":"Thiết lập n8n: Drive/Sheets Intake → Schema & Duplicate Check → AI Transaction Classification Draft → Invoice Match → Variance/Policy Check → Gmail Human Approval (Approve/Revise) → Approved Reconciliation Register → Dashboard Draft Refresh. Nhánh Revise quay về khâu phân loại/đối chiếu; không tự chuyển tiền, ghi sổ chính thức hay xác nhận giao dịch.","output":"n8n JSON, test log mẫu cho matched/unmatched/duplicate, bản ghi ngoại lệ và minh chứng nhánh Approve–Revise.","link":"Sản phẩm cuối khóa số 1, kết nối tri thức, báo cáo và dashboard."},{"number":9,"topic":"AI-Powered Web Development – Vibe Coding","title":"Two Responsive Websites: Portfolio & FinBridge Portal","description":"Xây dựng (1) Personal Finance & Banking Portfolio với CV, skills, case study và (2) FinBridge Operations Portal với Transaction Review, Cash Flow Overview, Budget Tracker, Document FAQ, Request Review Form. Kiểm tra responsive và giới hạn demo.","output":"2 website MVP (URL thử nghiệm nếu triển khai), desktop/mobile views, form có thông báo consent, không thu thập thông tin ngân hàng thật.","link":"Portal tích hợp chatbot ở buổi 10, portfolio tổng hợp 12 buổi."},{"number":10,"topic":"AI Chatbot Development – Finance Knowledge","title":"FinBridge Finance & Banking Research Assistant","description":"Tạo chatbot trả lời câu hỏi về cách đối chiếu sao kê, ý nghĩa cash-flow variance, giải thích các trường số liệu, khái niệm sản phẩm ngân hàng từ kiến thức đã kiểm chứng. Có citation cards và fallback “Ask the finance reviewer”. Không tư vấn đầu tư/cấp tín dụng cá nhân, không thực hiện giao dịch.","output":"Chat UI kèm 8–10 bộ test, source cards từ SOP & Methodology Notes, cơ chế escalation và cảnh báo educational demo.","link":"Sản phẩm cuối khóa số 3 cùng website."}]}];
